def group_rings(rings: list[list[int]]) -> list[tuple[int, list[int]]]:
    def _least_rotation(seq: list[int]) -> int:
        """Index of the lexicographically smallest rotation, in O(n)."""
        n = len(seq)
        if n <= 1:
            return 0

        doubled = seq + seq
        i, j, k = 0, 1, 0

        while i < n and j < n and k < n:
            a = doubled[i + k]
            b = doubled[j + k]

            if a == b:
                k += 1
            elif a > b:
                i += k + 1
                if i == j:
                    j += 1
                k = 0
            else:
                j += k + 1
                if i == j:
                    j += 1
                k = 0

        return min(i, j)

    def _min_period(seq: tuple[int, ...]) -> int:
        """
        Smallest p dividing len(seq) such that seq is repeated by p-blocks.
        Computed with the KMP prefix function in O(n).
        """
        n = len(seq)
        if n == 0:
            return 0
        if n == 1:
            return 1

        pi = [0] * n
        j = 0
        for i in range(1, n):
            x = seq[i]
            while j > 0 and x != seq[j]:
                j = pi[j - 1]
            if x == seq[j]:
                j += 1
            pi[i] = j

        p = n - pi[-1]
        if n % p == 0:
            return p
        return n

    groups: dict[tuple[int, ...], list] = {}
    order: list[tuple[int, ...]] = []

    for idx, ring in enumerate(rings):
        n = len(ring)

        # Build an exact canonical representative for the rotation class.
        if n == 0:
            key: tuple[int, ...] = ()
        elif n == 1:
            key = (ring[0],)
        elif n == 2:
            a, b = ring[0], ring[1]
            if a <= b:
                key = (a, b)
            else:
                key = (b, a)
        else:
            start = _least_rotation(ring)
            if start == 0:
                key = tuple(ring)
            else:
                key = tuple(ring[start:]) + tuple(ring[:start])

        group = groups.get(key)
        if group is None:
            if n == 0:
                period = 0
            elif n == 1:
                period = 1
            elif n == 2:
                period = 1 if key[0] == key[1] else 2
            else:
                period = _min_period(key)

            group = [period, [idx]]
            groups[key] = group
            order.append(key)
        else:
            group[1].append(idx)

    result = []
    for key in order:
        period, indices = groups[key]
        result.append((period, indices))
    return result
